import { createNativePlatform } from '../dist/platform.js';
import { ApprovedGit, discover } from '../dist/core/git.js';
import { loadPolicy } from '../dist/core/policy.js';
import { performance } from 'node:perf_hooks';
import { resolve } from 'node:path';
import { writeFileSync } from 'node:fs';
const root = resolve(import.meta.dirname, '..');
const base = 'C:/Users/tno/AppData/Local/Temp/angit stage1 BPqzUG';
const privateRoot = base + '/owner private/state/projects/prj_b9c7e84cc550284fb2133cc3ec9b088397ed1216aa949515';
const platform = createNativePlatform(root);
const repo = discover(platform, base + '/repository with spaces');
const policyPath = base + '/owner private/approved policy.json';
const policy = loadPolicy(platform, repo, policyPath, root);
const git = new ApprovedGit(platform, repo, policy.value.git, privateRoot);
const records = [];
for (const schedule of ['interval', 'completion-spaced']) {
  const started = performance.now();
  let timer, active = true, inspections = 0, inspectionMs = 0;
  const inspect = () => {
    const t = performance.now();
    const currentRepo = discover(platform, repo.root.canonicalPath);
    const currentPolicy = loadPolicy(platform, currentRepo, policyPath, root);
    if (currentRepo.repositoryIdentity !== repo.repositoryIdentity || currentPolicy.hash !== policy.hash) throw new Error('Readonly admission identity changed');
    inspectionMs += performance.now() - t; inspections++;
  };
  if (schedule === 'interval') timer = setInterval(inspect, policy.heartbeatIntervalMs);
  else {
    const next = () => { inspect(); if (active) timer = setTimeout(next, policy.heartbeatIntervalMs); };
    timer = setTimeout(next, policy.heartbeatIntervalMs);
  }
  const results = [];
  try {
    for (let i = 0; i < 3; i++) {
      const at = performance.now();
      const output = await git.run(['rev-parse', '--verify', 'HEAD']);
      results.push({ elapsedMs: performance.now() - at, oid: output.trim() });
    }
  } finally { active = false; clearInterval(timer); clearTimeout(timer); }
  records.push({ schedule, elapsedMs: performance.now() - started, inspections, inspectionMs, results });
}
const report = { schemaVersion: 'angit-local-observation/v1', scope: 'Readonly actual discover/loadPolicy heartbeat workload and approved Git progress; no grants/provider/repository mutations', heartbeatIntervalMs: policy.heartbeatIntervalMs, leaseDurationMs: policy.leaseDurationMs, records,
  limits: ['Specific earlier stalled coordinator attribution is inference', 'No policy/identity/lease/deadline checks weakened'] };
writeFileSync(resolve(root, 'evidence/stage2-heartbeat-progress-before.json'), JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify(report, null, 2));

