import { DatabaseSync } from 'node:sqlite';
import { Writable } from 'node:stream';
import { main } from '../dist/cli.js';
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
const base = 'C:/Users/tno/AppData/Local/Temp/angit stage1 BPqzUG';
const projectId = 'prj_b9c7e84cc550284fb2133cc3ec9b088397ed1216aa949515';
const stateRoot = base + '/owner private/state';
const workflow = stateRoot + '/projects/' + projectId + '/state.sqlite';
const observations = [];
for (let i = 0; i < 3; i++) {
  let output = '', errors = '';
  const at = performance.now();
  const exit = await main(['status', '--json'], { cwd: base + '/repository with spaces', coreOptions: { stateRoot }, interactive: false,
    stdout: new Writable({ write(bytes, encoding, done) { output += bytes.toString(); done(); } }),
    stderr: new Writable({ write(bytes, encoding, done) { errors += bytes.toString(); done(); } }) });
  const response = JSON.parse(output);
  if (exit || !response.ok || response.data.projectId !== projectId) throw new Error(output + errors);
  const publicElapsedMs = performance.now() - at;
  const before = performance.now();
  const db = new DatabaseSync(workflow, { readOnly: true, allowExtension: false, enableDoubleQuotedStringLiterals: false, timeout: 250 });
  let attempts;
  try { attempts = db.prepare('SELECT status,count(*) AS count FROM attempts WHERE project_id=? GROUP BY status').all(projectId); }
  finally { db.close(); }
  for (const row of attempts) if (response.data.attemptCounts[row.status] !== row.count) throw new Error('Public and readonly retained fixture projection differ');
  observations.push({ publicElapsedMs, readonlyProjectionElapsedMs: performance.now() - before, attempts });
}
const report = { schemaVersion: 'angit-local-observation/v1', scope: 'Readonly retained owned fixture public status versus fresh readonly SQLite projection; no state writes, approvals skipped or production caches; parallel lifecycle trace may add host contention', observations };
writeFileSync(resolve(import.meta.dirname, '../evidence/stage2-observer-cost.json'), JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify(report, null, 2));

