import { executionFixture, success, add, show } from '../tests/execution-fixture.mjs';
import { ApprovedGit } from '../dist/core/git.js';
import { WorktreeBroker } from '../dist/core/worktrees.js';
import { ExecutionSession } from '../dist/core/execution.js';
import { appendFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
const root = resolve(import.meta.dirname, '..');
const path = resolve(root, 'evidence/stage2-lifecycle-progress.json');
const tracePath = resolve(root, '.cache/lifecycle-progress.jsonl');
const origin = performance.now(), records = [];
writeFileSync(tracePath, '');
function record(value) { const row = { atMs: performance.now() - origin, ...value }; records.push(row); appendFileSync(tracePath, JSON.stringify(row) + '\n'); }
const restores = [];
for (const [prototype, name] of [[ApprovedGit.prototype, 'runBytes'], [WorktreeBroker.prototype, 'provision'], [WorktreeBroker.prototype, 'capture'], [ExecutionSession.prototype, 'assertLive']]) {
  const previous = prototype[name]; restores.push(() => { prototype[name] = previous; });
  if (name === 'assertLive') prototype[name] = function (...args) { const at = performance.now(); try { return previous.apply(this, args); } finally { record({ method: name, durationMs: performance.now() - at }); } };
  else prototype[name] = async function (...args) { const at = performance.now(); record({ method: name, phase: 'begin', args: name === 'runBytes' ? args[0] : undefined }); try { const value = await previous.apply(this, args); record({ method: name, phase: 'end', durationMs: performance.now() - at }); return value; } catch (error) { record({ method: name, phase: 'failed', durationMs: performance.now() - at, code: error.code, message: error.message }); throw error; } };
}
const f = executionFixture({ modes: ['commit'], parallel: 2 });
let result, states, failure, cleanup;
try {
  record({ phase: 'fixture-ready', ownedFixture: f.base });
  await success(f, f.initArgs); await add(f, 'tsk_a'); await add(f, 'tsk_b');
  record({ phase: 'run-begin' });
  result = await f.command(['run', '--parallel', '2', '--until', 'idle', '--idempotency-key', 'trace-run', '--json']);
  record({ phase: 'run-end', exit: result.exit, result: result.result });
  states = [await show(f, 'tsk_a'), await show(f, 'tsk_b')];
} catch (error) { failure = { code: error.code, message: error.message, stack: error.stack }; }
finally {
  for (const restore of restores) restore();
  try { await f.cleanup(); cleanup = 'owned fixture removed after resolved lifecycle'; } catch (error) { cleanup = error.message; }
  const report = { schemaVersion: 'angit-local-observation/v1', scope: 'Actual two-task foreground run with real inert native profiles; duration trace only, unchanged permissions/deadlines/leases and no status-query polling during execution', durationMs: performance.now() - origin, result, states, failure, cleanup, records };
  writeFileSync(path, JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify({ durationMs: report.durationMs, result, failure, cleanup, counts: Object.fromEntries(['runBytes', 'provision', 'capture', 'assertLive'].map(method => [method, records.filter(row => row.method === method).length])) }, null, 2));
  if (failure || result?.result?.ok !== true || states?.some(state => state.task.status !== 'submitted')) process.exitCode = 1;
}
